+    {
+        // ~30 % chance each poll cycle to add a new notification
+        if (Random.Shared.Next(100) >= 30)
+            return;
+
+        string[] templates =
+        [
+            "You have a new follower!",
+            "Someone liked your post.",
+            "Scheduled maintenance tonight at 11 PM.",
+            "Your export is ready for download.",
+            "A team member mentioned you in a comment.",
+        ];
+
+        lock (_lock)
+        {
+            var msg = templates[Random.Shared.Next(templates.Length)];
+            _notifications.Add(new Notification(_nextId++, msg, DateTime.UtcNow));
+        }
+    }
+}
